import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [query, setQuery] = useState('java');
  const [location, setLocation] = useState('remote');
  const [titleFilter, setTitleFilter] = useState('');
  const [companyFilter, setCompanyFilter] = useState('');
  const [message, setMessage] = useState('');

  const loadJobs = () => {
    setLoading(true);
    setError(null);
    fetch('http://localhost:8080/api/jobs')
      .then((response) => response.json())
      .then((data) => {
        setJobs(data);
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  };

  useEffect(() => {
    loadJobs();
  }, []);

  const handleScrape = () => {
    setMessage('Scraping Dice...');
    fetch(`http://localhost:8080/api/jobs/scrape/dice?query=${encodeURIComponent(query)}&location=${encodeURIComponent(location)}`, {
      method: 'POST',
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error('Scrape failed');
        }
        return response.json();
      })
      .then((data) => {
        setMessage(`Saved ${data.length} scraped jobs.`);
        setJobs(data);
      })
      .catch((err) => {
        setError(err.message);
        setMessage('');
      });
  };

  const handleFilter = () => {
    setMessage('Applying filters...');
    fetch('http://localhost:8080/api/jobs/filter', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: titleFilter,
        company: companyFilter,
        location,
      }),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error('Filter request failed');
        }
        return response.json();
      })
      .then((data) => {
        setJobs(data);
        setMessage(`Found ${data.length} matching jobs.`);
      })
      .catch((err) => {
        setError(err.message);
        setMessage('');
      });
  };

  const handleCandidateSearch = () => {
    // Search for the current query as a candidate-focused search:
    // only C2C, visa GC (heuristic), and interview offline
    setMessage('Searching jobs for candidate (C2C, GC, offline)...');
    fetch('http://localhost:8080/api/jobs/filter', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: query,
        onlyC2C: true,
        interviewOffline: true,
        visaGC: true
      }),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error('Filter request failed');
        }
        return response.json();
      })
      .then((data) => {
        setJobs(data);
        setMessage(`Found ${data.length} matching jobs for candidate.`);
      })
      .catch((err) => {
        setError(err.message);
        setMessage('');
      });
  };

  if (loading) {
    return <div className="App">Loading jobs...</div>;
  }

  if (error) {
    return <div className="App">Error: {error}</div>;
  }

  return (
    <div className="App">
      <h1>C2C Job Sourcer</h1>

      <div className="control-panel">
        <div className="control-group">
          <label>Scrape query</label>
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Job title or keyword" />
        </div>
        <div className="control-group">
          <label>Location</label>
          <input value={location} onChange={(e) => setLocation(e.target.value)} placeholder="remote or city" />
        </div>
        <button onClick={handleScrape}>Scrape Dice</button>
      </div>

      <div className="control-panel">
        <div className="control-group">
          <label>Title filter</label>
          <input value={titleFilter} onChange={(e) => setTitleFilter(e.target.value)} placeholder="Software Engineer" />
        </div>
        <div className="control-group">
          <label>Company filter</label>
          <input value={companyFilter} onChange={(e) => setCompanyFilter(e.target.value)} placeholder="Company name" />
        </div>
        <button onClick={handleFilter}>Apply Filters</button>
        <button onClick={handleCandidateSearch} style={{ marginLeft: '8px' }}>Search for Candidate</button>
      </div>

      {message && <div className="status-message">{message}</div>}

      <div className="job-list">
        {jobs.map((job) => (
          <div key={job.id} className="job-card">
            <h2>{job.title || 'Untitled'}</h2>
            <p><strong>Company:</strong> {job.company || 'Unknown'}</p>
            <p><strong>Location:</strong> {job.location || 'N/A'}</p>
            <p><strong>Source:</strong> {job.source || 'N/A'}</p>
            <a href={job.url} target="_blank" rel="noreferrer">View job</a>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
